#include <bits/stdc++.h>
using namespace std;
int parent_[751];
int find_(int x){ return parent_[x]==x?x:parent_[x]=find_(parent_[x]); }
int main(){
    int n;
    while (cin >> n) {
        vector<double> x(n+1), y(n+1);
        for (int i=1;i<=n;i++) cin >> x[i] >> y[i];
        for (int i=1;i<=n;i++) parent_[i]=i;
        int m; cin >> m;
        int comps = n;
        for (int i=0;i<m;i++){
            int a,b; cin >> a >> b;
            int ra=find_(a), rb=find_(b);
            if (ra!=rb){ parent_[ra]=rb; comps--; }
        }
        vector<tuple<double,int,int>> edges;
        for (int i=1;i<=n;i++) for (int j=i+1;j<=n;j++) {
            double d = hypot(x[i]-x[j], y[i]-y[j]);
            edges.push_back(make_tuple(d,i,j));
        }
        sort(edges.begin(), edges.end());
        double total=0;
        for (auto& e : edges) {
            if (comps==1) break;
            double d=get<0>(e); int a=get<1>(e), b=get<2>(e);
            int ra=find_(a), rb=find_(b);
            if (ra!=rb){ parent_[ra]=rb; comps--; total+=d; }
        }
        printf("%.2f\n", total);
    }
}

